<template>
 <section class="music-piano" :class="{'read-only':readOnly}" :aria-label="$t('Piano Roll')" :style="{'--note-color':color}">
  <div class="piano-ruler"><span>{{ $t('Notas') }}</span><MusicTimeRuler :width="gridWidth" :start="start" :span="span" :cursor="cursor" @seek="$emit('seek',$event)" @scrub-start="$emit('scrub-start')" @scrub-end="$emit('scrub-end')" /></div>
  <div ref="scroll" class="piano-scroll" @scroll="$emit('scroll',$event.target.scrollTop)" @wheel="wheel">
   <div class="piano-surface" :style="{height:96*rowHeight+'px'}">
    <div class="piano-keys"><button v-for="pitch in pitches" :key="pitch" :style="{top:(95-pitch)*rowHeight+'px',height:rowHeight+'px'}" :class="{black:isBlack(pitch),octave:pitch%12===0}" :aria-label="noteName(pitch)" :title="$t('El piano indica alturas; la escucha se realiza en Emulador.')" @click="$emit('pitch',pitch)">{{noteName(pitch)}}</button></div>
    <svg ref="grid" class="piano-grid" :width="gridWidth" :height="96*rowHeight" role="group" :aria-label="$t('Piano roll SPC700')" @pointerdown="beginArea" @pointermove="move" @pointerup="finish" @pointercancel="cancel">
     <rect v-for="pitch in pitches" :key="pitch" x="0" :y="(95-pitch)*rowHeight" :width="gridWidth" :height="rowHeight" :fill="isBlack(pitch)?'#152131':'#1c2a3b'" :stroke="pitch%12===0?'#50627a':'#29384b'" stroke-width=".5" />
     <line v-for="tick in ticks" :key="tick" :x1="x(tick)" y1="0" :x2="x(tick)" :y2="96*rowHeight" :stroke="tick%192===0?'#667c98':'#304058'" :opacity="tick%192===0?.65:.65" />
     <g v-for="entry in visible" :key="entry.index" :transform="transform(entry.index)">
      <rect data-note="true" class="piano-note" :class="{selected:isSelected(entry.index)}" :x="x(entry.note.tick)" :y="(95-entry.note.pitch)*rowHeight+1" :width="noteWidth(entry)" :height="rowHeight-2" rx="2" tabindex="0" role="button" :aria-label="`${noteName(entry.note.pitch)} · ${entry.note.tick}`" @pointerdown.stop="beginNote($event,entry,'move')" @keydown.enter.prevent="$emit('select',[{channel,index:entry.index}])"><title>{{noteName(entry.note.pitch)}} · {{entry.note.tick}} · {{entry.note.duration}}</title></rect>
      <text v-if="entry.note.duration/span*gridWidth>34&&rowHeight>=16" :x="x(entry.note.tick)+5" :y="(95-entry.note.pitch)*rowHeight+rowHeight-5" font-size="9" fill="#102331" pointer-events="none">{{noteName(entry.note.pitch)}}</text>
      <rect v-if="editable&&!readOnly" data-note="true" class="note-resize" :x="x(entry.note.tick)+noteWidth(entry)-3" :y="(95-entry.note.pitch)*rowHeight+1" width="8" :height="rowHeight-2" @pointerdown.stop="beginNote($event,entry,'resize')"><title>{{ $t('Arrastra para acortar o alargar la nota') }}</title></rect>
     </g>
     <rect v-if="drag?.kind==='area'" :x="Math.min(drag.x,drag.currentX)" :y="Math.min(drag.y,drag.currentY)" :width="Math.abs(drag.currentX-drag.x)" :height="Math.abs(drag.currentY-drag.y)" fill="#84c7ff22" stroke="#84c7ff" pointer-events="none" />
     
    </svg>
    <MusicTimeRuler marker-only :offset="72" :width="gridWidth" :start="start" :span="span" :cursor="cursor" @seek="$emit('seek',$event)" @scrub-start="$emit('scrub-start')" @scrub-end="$emit('scrub-end')" />
   </div>
  </div>
 </section>
</template>
<script>
import MusicTimeRuler from './MusicTimeRuler.vue';import {clamp,noteName,snapTick,timelineRatio,timelineTime} from '../editor/timeline.mjs';
export default {components:{MusicTimeRuler},props:{track:Object,channel:Number,selection:Array,start:Number,span:Number,width:Number,rowHeight:Number,snap:Number,color:String,cursor:Number,editable:Boolean,tool:String,scrollTop:Number,readOnly:Boolean},emits:['select','edit','seek','scrub-start','scrub-end','scroll','pan','zoom','pitch'],data(){return {drag:null};},
 computed:{selectionKeys(){return new Set(this.selection.map(n=>`${n.channel}:${n.index}`));},gridWidth(){return Math.max(180,this.width-72);},pitches(){return Array.from({length:96},(_,i)=>95-i);},visible(){return this.track.notes.map((note,index)=>({note,index})).filter(({note})=>note.tick+note.duration>=this.start&&note.tick<=this.start+this.span);},ticks(){const step=this.span/this.gridWidth>2?Math.max(192,Math.ceil(this.span/this.gridWidth*64/192)*192):this.span/this.gridWidth>.7?48:Math.max(6,this.snap);return Array.from({length:Math.ceil(this.span/step)+1},(_,i)=>Math.ceil(this.start/step)*step+i*step);}},
 watch:{channel(){this.restoreScroll();},rowHeight(value,old){if(this.$refs.scroll)this.$refs.scroll.scrollTop=this.$refs.scroll.scrollTop/old*value;}},mounted(){this.restoreScroll();},
 methods:{noteName,isBlack(pitch){return [1,3,6,8,10].includes(pitch%12);},x(tick){return timelineRatio(tick,this.start,this.span)*this.gridWidth;},isSelected(index){return this.selectionKeys.has(`${this.channel}:${index}`);},
  restoreScroll(){this.$nextTick(()=>{if(!this.$refs.scroll)return;const max=this.track.notes.length?Math.max(...this.track.notes.map(n=>n.pitch)):72;this.$refs.scroll.scrollTop=this.scrollTop??Math.max(0,(95-max)*this.rowHeight-65);});},
  point(e){const b=this.$refs.grid.getBoundingClientRect();return {x:clamp(e.clientX-b.left,0,this.gridWidth),y:clamp(e.clientY-b.top,0,96*this.rowHeight-1)};},
  beginNote(e,entry,kind){if(e.button!==0)return;e.preventDefault();this.$refs.grid.setPointerCapture(e.pointerId);const ref={channel:this.channel,index:entry.index},selected=this.isSelected(entry.index),add=e.shiftKey||e.ctrlKey||e.metaKey;let refs=add?(selected?this.selection.filter(n=>n.channel!==this.channel||n.index!==entry.index):[...this.selection,ref]):selected?this.selection:[ref];this.$emit('select',refs);if(this.readOnly)return;this.drag={kind,refs,x:e.clientX,y:e.clientY,dx:0,dy:0,singleOnClick:!add&&selected&&refs.length>1?ref:null};},
  beginArea(e){if(e.button!==0||e.target.dataset.note)return;e.preventDefault();this.$refs.grid.setPointerCapture(e.pointerId);const p=this.point(e);this.drag={kind:'area',...p,currentX:p.x,currentY:p.y,add:e.shiftKey||e.ctrlKey||e.metaKey};},
  move(e){const d=this.drag;if(!d)return;if(d.kind==='area'){const p=this.point(e);d.currentX=p.x;d.currentY=p.y;return;}d.dx=this.editable?Math.round((e.clientX-d.x)/this.gridWidth*this.span/this.snap)*this.snap:0;if(d.kind==='resize'){const durations=d.refs.filter(n=>n.channel===this.channel).map(n=>this.track.notes[n.index].duration);if(durations.length)d.dx=clamp(d.dx,1-Math.min(...durations),255-Math.max(...durations));}d.dy=d.kind==='resize'?0:-Math.round((e.clientY-d.y)/this.rowHeight);},
  resizeDelta(index){const d=this.drag;return d?.kind==='resize'&&d.refs.some(n=>n.channel===this.channel&&n.index===index)?d.dx:0;},noteWidth(entry){return Math.max(4,(entry.note.duration+this.resizeDelta(entry.index))/this.span*this.gridWidth);},
  transform(index){const d=this.drag;if(!d||d.kind!=='move'||!d.refs.some(n=>n.channel===this.channel&&n.index===index))return '';return `translate(${d.dx/this.span*this.gridWidth},${-d.dy*this.rowHeight})`;},
  finish(){const d=this.drag;this.drag=null;if(!d)return;if(d.kind==='area'){
   const small=Math.abs(d.currentX-d.x)<4&&Math.abs(d.currentY-d.y)<4;
   if(small&&this.tool==='draw'&&this.editable&&!this.readOnly){this.$emit('edit',{type:'add',channel:this.channel,note:{tick:snapTick(timelineTime(d.x/this.gridWidth,this.start,this.span),this.snap),pitch:95-Math.floor(d.y/this.rowHeight),duration:Math.max(1,this.snap),velocity:100}});return;}
   const minT=timelineTime(Math.min(d.x,d.currentX)/this.gridWidth,this.start,this.span),maxT=timelineTime(Math.max(d.x,d.currentX)/this.gridWidth,this.start,this.span),high=95-Math.floor(Math.min(d.y,d.currentY)/this.rowHeight),low=95-Math.floor(Math.max(d.y,d.currentY)/this.rowHeight);
   const refs=this.track.notes.flatMap((n,index)=>n.tick<=maxT&&n.tick+n.duration>=minT&&n.pitch>=low&&n.pitch<=high?[{channel:this.channel,index}]:[]),all=d.add?[...this.selection,...refs]:refs;this.$emit('select',[...new Map(all.map(n=>[`${n.channel}:${n.index}`,n])).values()]);
   if(small)this.$emit('seek',snapTick(minT,this.snap));return;
  }if(!d.dx&&!d.dy){if(d.singleOnClick)this.$emit('select',[d.singleOnClick]);return;}this.$emit('edit',{type:'modify',refs:d.refs,...(d.kind==='resize'?{durationDelta:d.dx}:{tickDelta:d.dx,pitchDelta:d.dy})});},
  cancel(){this.drag=null;},wheel(e){if(e.ctrlKey||e.metaKey){e.preventDefault();this.$emit('zoom',Math.exp(clamp(e.deltaY*.002,-1,1)));}else if(e.shiftKey||Math.abs(e.deltaX)>Math.abs(e.deltaY)){e.preventDefault();this.$emit('pan',(e.deltaX||e.deltaY)/this.gridWidth*this.span);}}
 }};
</script>
<style scoped>
.music-piano{height:100%;min-height:0;display:flex;flex-direction:column}.piano-ruler{display:flex;flex-shrink:0}.piano-ruler>span{width:72px;flex-shrink:0;padding:8px;box-sizing:border-box;background:#263447;font-size:10px;color:#afc4dc}.piano-scroll{min-height:0;flex:1;overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain;background:#152131}.piano-surface{display:flex;position:relative}.piano-keys{position:relative;width:72px;flex-shrink:0;background:#d8e1ea;z-index:2}.piano-keys button{position:absolute;left:0;width:100%;padding:0 7px;text-align:right;border:0;border-bottom:1px solid #8f9cac;border-radius:0;background:#dbe6ed;color:#36495e;font:10px monospace;cursor:default}.piano-keys button.black{width:78%;background:#253342;color:#b5c6d8;box-shadow:2px 1px 2px #0008}.piano-keys button.octave{color:#0f6c86;background:#bde0e4;font-weight:bold}.piano-grid{flex-shrink:0;display:block;user-select:none;touch-action:none;cursor:crosshair}.piano-note{fill:var(--note-color);stroke:#ffffff40;stroke-width:.7;cursor:grab;touch-action:none}.piano-note.selected{fill:#f0cb80;stroke:#fff0cb;stroke-width:1.5}.piano-note:focus-visible{outline:none;stroke:#fff;stroke-width:2}.note-resize{fill:#ffffff70;stroke:#ffffff80;stroke-width:.5;cursor:ew-resize;touch-action:none}.read-only .piano-note{cursor:pointer}.note-resize:hover{fill:#fff;stroke:#fff}
</style>
